#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005

long long a[MAXN];
long long b[MAXN];
long long c[MAXN];

int cmp_desc(const void *p1, const void *p2) {
    long long x = *(const long long *)p1;
    long long y = *(const long long *)p2;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
    }
    for (int i = 0; i < n; i++) {
        scanf("%lld", &b[i]);
    }

    long long ans = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] > b[i]) {
            ans += (a[i] - b[i]);
            c[i] = b[i];
        } else {
            c[i] = a[i];
        }
    }

    qsort(c, n, sizeof(long long), cmp_desc);

    int take = k + 1;
    if (take > n) take = n;

    for (int i = 0; i < take; i++) {
        ans += c[i];
    }

    printf("%lld\n", ans);

    return 0;
}
